"""Reaction/discussion previews generated by ChatGPT from a template thumbnail.

Template sources per streamer:
  auto   — thumbnails of other clip channels of the same streamer (found on YouTube)
  manual — images the user put into thumbnail_templates/<login>/
The prompt asks ChatGPT to remake the template with the clip's caption and context.
"""
from __future__ import annotations
import json
import os
import random
import re
import subprocess
import sys
import tempfile
import time
from pathlib import Path

# The opening can be changed per streamer on the «Превью» page (pipeline.preview.prompts);
# the bot always appends the clip's caption and «контекст: …» after it.
DEFAULT_INTRO=('Сделай мне такое же превью, но конечно улучши его визуально, более кликабельным сделай + улучши визуально текст '
               'и измени его на мой:')
PROMPT=DEFAULT_INTRO+' {text}\n\nконтекст: {context}'


def prompt_intro(cfg,login):
    value=((cfg or {}).get('prompts') or {}).get(str(login or '').lower())
    return value.strip() if isinstance(value,str) and value.strip() else DEFAULT_INTRO


def build_prompt(cfg,login,text,context):
    # Plain concatenation: braces or other symbols in the user's text are kept as typed.
    return prompt_intro(cfg,login)+' '+text+'\n\nконтекст: '+context
IMAGE_EXT=('.jpg','.jpeg','.png','.webp')
AUTO_DIR='_auto'
MAX_AUTO=30
CLIP_WORDS=('нарезк','clips','cuts','highlight','перемотк','свалк','моменты','лучшее')


def manual_dir(root,login):
    return Path(root)/'thumbnail_templates'/str(login).lower()


def auto_dir(root,login):
    return Path(root)/'thumbnail_templates'/AUTO_DIR/str(login).lower()


def list_images(folder):
    folder=Path(folder)
    if not folder.is_dir():return []
    return sorted(p for p in folder.iterdir() if p.is_file() and p.suffix.lower() in IMAGE_EXT and not p.name.startswith('.'))


def template_mode(cfg,login):
    return ((cfg or {}).get('templates') or {}).get(str(login).lower(),'auto')


# Как англоязычных стримеров называют в YouTube (первое — для поиска); ник Twitch часто не совпадает.
EN_ALIASES={'kaicenat':['kai cenat'],'caseoh_':['caseoh'],'zackrawrr':['asmongold'],'hasanabi':['hasanabi','hasan'],
            'ishowspeed':['ishowspeed'],'xqc':['xqc'],'tfue':['tfue'],'adinross':['adin ross'],'sketch':['sketch']}


_TR=(('shch','щ'),('sch','щ'),('yo','ё'),('yu','ю'),('ya','я'),('ye','е'),('zh','ж'),('kh','х'),('ts','ц'),('ch','ч'),('sh','ш'),('ck','к'),
     ('a','а'),('b','б'),('c','к'),('d','д'),('e','е'),('f','ф'),('g','г'),('h','х'),('i','и'),('j','дж'),('k','к'),('l','л'),('m','м'),
     ('n','н'),('o','о'),('p','п'),('q','к'),('r','р'),('s','с'),('t','т'),('u','у'),('v','в'),('w','в'),('x','кс'),('y','й'),('z','з'))


def _translit(name):
    """strogo → строго: русское написание латинского ника (для поиска и узнавания в русских названиях)."""
    s=re.sub(r'[\d_]+',' ',str(name or '').lower()).strip()
    if not s or not re.fullmatch(r'[a-z ]+',s):return ''
    out='';i=0
    while i<len(s):
        for lat,cyr in _TR:
            if s.startswith(lat,i):out+=cyr;i+=len(lat);break
        else:
            out+=s[i];i+=1
    return out.strip()


def _aliases(login):
    """Имена стримера: логин, варианты из EN_ALIASES / config.preview_aliases; последнее — для поисковых запросов."""
    l=str(login).lower().strip()
    try:
        import youtube_titles
        alias=youtube_titles.ALIASES.get(l)
    except Exception:
        alias=None
    extra=[]
    try:
        import lang
        v=(lang._config().get('preview_aliases') or {}).get(l)
        extra+=[v] if isinstance(v,str) else list(v or [])
    except Exception:
        pass
    extra+=EN_ALIASES.get(l) or []
    plain=re.sub(r'_+',' ',l).strip()    # caseoh_ → caseoh
    query=str(alias or (extra[0] if extra else plain)).lower().strip()
    cyr=_translit(plain) if not (alias or extra) else ''
    names=[n for n in dict.fromkeys(str(x).lower().strip() for x in [l,plain,*extra,alias or '',cyr] if x) if n and n!=query]
    return names+[query]


def _own_channels(root):
    try:
        from youtube_queue import YouTubeQueue
        return {p['channel_id'] for p in YouTubeQueue(Path(root)/'state'/'jobs.sqlite3').list_profiles()}
    except Exception:
        return set()


def _ytdlp_json(args,timeout=60,lang='ru'):
    cmd=[sys.executable,'-m','yt_dlp','--ignore-config','--no-warnings','--flat-playlist','--dump-single-json',
         '--extractor-args','youtube:lang='+lang,'--socket-timeout','15',*args]
    p=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=timeout,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
    if p.returncode:raise RuntimeError('YouTube-поиск не удался: '+p.stderr.decode('utf-8','replace')[-200:])
    return json.loads(p.stdout)


# ---------- лучший канал-нарезчик стримера ----------
TAKE=10               # сколько последних превью забирать с лучшего канала за раз
REFRESH_DAYS=14       # раз в сколько дней обновлять (снова последние TAKE с канала)
KEEP=30               # сколько последних образцов держать в папке
FRESH_DAYS=35         # канал считается живым, если последнее видео не старше
STALE_DAYS=90         # старше — канал берётся, только если других нет
CLIP_HINTS=CLIP_WORDS+('резк','обрезк','рофл','каждый день','стрим','clip','highlight','moment','compilation','daily','best of','funny','vod')


def _age_days(text):
    """«3 дня назад», «1 мес. назад», «2 weeks ago» → дни (или None)."""
    t=str(text or '').lower()
    m=re.search(r'(\d+)\s*(секунд|минут|мин|час|ч\b|дн|день|недел|нед|месяц|мес|год|лет|second|minute|hour|day|week|month|year)',t)
    if not m:return None
    unit=m.group(2)
    for key,days in (('секунд',1/86400),('second',1/86400),('минут',1/1440),('мин',1/1440),('minute',1/1440),('час',1/24),('ч',1/24),('hour',1/24),
                     ('дн',1),('день',1),('day',1),('недел',7),('нед',7),('week',7),('месяц',30),('мес',30),('month',30),('год',365),('лет',365),('year',365)):
        if unit.startswith(key):return int(m.group(1))*days
    return None


def _name_forms(login):
    """Логин и псевдоним + основа русского имени (Каша → каш: Каши, Кашу, Кашерезка)."""
    forms=set()
    for n in _aliases(login):
        n=n.lower().strip()
        forms.add(n)
        if len(n)>=4 and n[-1] in 'аяьйыо':forms.add(n[:-1])
        forms.add(n.replace(' ',''))
    return {f for f in forms if len(f)>=3}


def _streamer_channel_ids(root,login):
    """YouTube-каналы самого стримера (из ссылок на Twitch) — их превью брать нельзя."""
    ids=set()
    try:
        import youtube_descriptions as yd, channel_stats as cs
        for x in yd.fetch_links(root,login).get('links') or []:
            url=str(x.get('url') or '')
            if 'youtube.com' not in url and 'youtu.be' not in url:continue
            m=re.search(r'/channel/(UC[\w-]{22})',url)
            if m:ids.add(m.group(1));continue
            try:
                html=cs._Client().page(url)
                m=re.search(r'"(?:channelId|externalId)":"(UC[\w-]{22})"',html)
                if m:ids.add(m.group(1))
            except Exception:
                pass
    except Exception:
        pass
    return ids


# ---------- каналы-образцы, заданные вручную ----------
def pinned_channels(login,cfg=None):
    """Каналы для образцов превью, заданные вручную: config.json → pipeline.preview.channels[login].
    Ссылки (https://www.youtube.com/@xQcOW/videos), @handle или UC-id; берутся всегда, даже канал самого стримера."""
    if cfg is None:
        try:
            import lang
            cfg=((lang._config().get('pipeline') or {}).get('preview')) or {}
        except Exception:
            cfg={}
    v=((cfg or {}).get('channels') or {}).get(str(login or '').lower())
    if isinstance(v,str):v=re.split(r'[\s,;]+',v)
    return list(dict.fromkeys(str(x).strip() for x in (v or []) if str(x).strip()))


def _channel_url(ref):
    r=str(ref).strip()
    if re.fullmatch(r'UC[\w-]{22}',r):return f'https://www.youtube.com/channel/{r}'
    if r.startswith('@'):return 'https://www.youtube.com/'+r
    if not re.match(r'https?://',r):r='https://'+r.lstrip('/')
    return r


def resolve_channel_id(client,ref):
    """Ссылка / @handle / UC-id канала → UC-id."""
    r=str(ref).strip()
    if re.fullmatch(r'UC[\w-]{22}',r):return r
    m=re.search(r'/channel/(UC[\w-]{22})',r)
    if m:return m.group(1)
    html=client.page(_channel_url(r))
    for pat in (r'"externalId":"(UC[\w-]{22})"',r'itemprop="identifier" content="(UC[\w-]{22})"',
                r'<link rel="canonical" href="https://www\.youtube\.com/channel/(UC[\w-]{22})"',r'"channelId":"(UC[\w-]{22})"'):
        m=re.search(pat,html)
        if m:return m.group(1)
    raise RuntimeError('не удалось определить канал по ссылке')


def _source_row(p,extra=None):
    recent=p['videos'][:12]
    ages=[v['age'] for v in recent if v['age'] is not None]
    views=sorted(v['views'] for v in recent[:10])
    row={'id':p['id'],'title':p['title'],'subs':p['subs'],'median_views':views[len(views)//2] if views else 0,
         'last_days':min(ages) if ages else None,'about':1.0,'score':None,'videos':p['videos']}
    row.update(extra or {})
    return row


def _channel_profile(client,cid):
    import channel_stats as cs
    html=client.page(f'https://www.youtube.com/channel/{cid}/videos')
    data=cs._initial(html)
    meta=next((x for x in cs._walk(data,'channelMetadataRenderer') if isinstance(x,dict)),{})
    m=re.search(r'"content":"([^"]{0,40}(?:подписчик|subscriber)[^"]{0,15})"',html)
    subs=(cs.parse_count(m.group(1)) if m else 0) or 0
    videos=[]
    for v in cs._walk(data,'lockupViewModel'):
        if not isinstance(v,dict) or v.get('contentType') not in (None,'LOCKUP_CONTENT_TYPE_VIDEO'):continue
        vid=v.get('contentId')
        if not isinstance(vid,str) or not re.fullmatch(r'[A-Za-z0-9_-]{11}',vid):continue
        md=(v.get('metadata') or {}).get('lockupMetadataViewModel') or {}
        labels=[x for x in cs._walk(md,'accessibilityLabel') if isinstance(x,str)]+[x for x in cs._walk(md,'content') if isinstance(x,str)]
        age=next((a for a in (_age_days(x) for x in labels if re.search(r'назад|ago',x)) if a is not None),None)
        views=next((cs.parse_count(x) for x in labels if re.search(r'просмотр|view',x,re.I) and cs.parse_count(x) is not None),0)
        title=((md.get('title') or {}).get('content')) or ''
        videos.append({'id':vid,'title':title,'views':views or 0,'age':age})
    return {'id':cid,'title':meta.get('title') or '','subs':subs,'videos':videos}


def rank_clip_channels(root,login,log=print,limit=12):
    """Каналы-нарезчики стримера, лучшие первыми: подписчики, свежесть последнего видео, просмотры относительно других.
    Отсекаются сам стример (его YouTube из ссылок Twitch и каналы с его именем без признаков нарезок) и наши каналы."""
    import lang, channel_stats as cs, math
    en=lang.is_en() or lang.for_streamer(login)=='en'    # кнопка в «Превью» работает в своём потоке без языка
    names=_aliases(login);forms=_name_forms(login);own=_own_channels(root)|_streamer_channel_ids(root,login)
    alias=names[-1]
    queries=([f'{alias} clips',f'{alias} highlights',f'{alias} funny moments',f'{alias} best moments',f'best of {alias}',
              f'{alias} clip channel',f'{alias} reacts',f'{alias} rage moments']+
             ([f'{names[0]} clips',f'{names[0]} highlights'] if names[0]!=alias else []) if en else
             [f'{alias} нарезки',f'нарезки {alias}',f'{login} нарезки',f'{alias} смотрит',f'{alias} лучшие моменты']+
             [q for n in names if re.search('[а-яё]',n) for q in (f'{n} нарезки',f'нарезки {n}',f'{n} смотрит',f'{n} реакция',f'{n} лучшие моменты')])
    hits={};names_seen={}
    for q in dict.fromkeys(queries):
        try:data=_ytdlp_json([('ytsearch50:' if en else 'ytsearch30:')+q],timeout=120,lang='en' if en else 'ru')
        except Exception as exc:
            log(f'Поиск «{q}» не удался: {type(exc).__name__}');continue
        for e in data.get('entries') or []:
            cid=e.get('channel_id');cname=(e.get('channel') or e.get('uploader') or '').strip()
            if not cid or cid in own:continue
            hits[cid]=hits.get(cid,0)+1;names_seen[cid]=cname
    client=cs._Client();rows=[];weak=[]
    for cid in sorted(hits,key=lambda c:-hits[c])[:limit+8 if en else limit]:
        try:p=_channel_profile(client,cid)
        except Exception as exc:
            log(f'Канал «{names_seen[cid]}»: страница не прочитана ({type(exc).__name__})');continue
        recent=p['videos'][:12]
        if len(recent)<3:continue    # почти нет длинных видео — не из чего брать превью
        low=(p['title'] or names_seen[cid]).lower()
        squash={f.replace(' ','') for f in forms}
        about=sum(1 for v in recent if any(f in v['title'].lower() for f in forms)
                  or any(f in re.sub(r'[\W_]+','',v['title'].lower()) for f in squash))/len(recent)
        clip_name=any(w in low for w in CLIP_HINTS)
        bare_name=re.sub(r'\b(tv|official|yt)\b','',low).replace(' ','') in {f.replace(' ','') for f in names}   # основной канал стримера: просто его имя
        # Отдельный канал с именем стримера + что-то ещё («Jynxzi Live», «Каша стрим»): реакции и нарезки стримов.
        named=not bare_name and any(f.replace(' ','') in low.replace(' ','') for f in forms)
        if bare_name and not clip_name:continue
        # Нарезчик почти в каждом видео пишет имя стримера; свой канал стримера (и чужой стример) — редко.
        target=rows if len(recent)>=5 else weak    # маленький канал — только если больше некого
        # Канал с именем стримера отдельным словом («Kai Cenat Live», «Asmongold Clips»), часто в выдаче и крупный —
        # его ролики могут не повторять имя в названии, но канал явно про этого стримера.
        named_strong=named and hits[cid]>=5 and p['subs']>=10000 and \
            any(re.search(r'(?<![\w])'+re.escape(f)+r'(?![\w])',low) for f in forms)
        if about<0.7 and not (clip_name and about>=0.4) and not (named and about>=0.3) and not named_strong:
            if not (clip_name and about>=0.1):continue
            target=weak    # общий канал нарезок: берётся, только если нет нарезчиков именно этого стримера
        ages=[v['age'] for v in recent if v['age'] is not None]
        last=min(ages) if ages else None
        views=sorted(v['views'] for v in recent[:10]);median=views[len(views)//2] if views else 0
        target.append({'id':cid,'title':p['title'] or names_seen[cid],'subs':p['subs'],'median_views':median,'last_days':last,
                     'about':round(about,2),'hits':hits[cid],'videos':p['videos']})
    rows=rows or weak
    if not rows:return []
    top_views=max(r['median_views'] for r in rows) or 1
    for r in rows:
        last=r['last_days'] if r['last_days'] is not None else 999
        fresh=1.0 if last<=FRESH_DAYS else 0.7 if last<=STALE_DAYS else 0.15
        r['score']=round(fresh*(math.log10(r['subs']+10)+2*math.log10(r['median_views']+10)-math.log10(top_views+10)+0.1*min(r['hits'],10)),3)
    rows.sort(key=lambda r:-r['score'])
    return rows


def find_clip_channels(root,login,log=print):
    """Совместимость: [(id, название, оценка)] лучших каналов-нарезчиков."""
    return [(r['id'],r['title'],r['score']) for r in rank_clip_channels(root,login,log)[:4]]


AUTO_WITH_PINNED=2    # сколько лучших найденных нарезчиков добавлять к каналам, заданным вручную
AUTO_NO_PINNED=3      # без ручных каналов — до стольких лучших нарезчиков (не слабее 70% от лучшего)


def refresh_auto(root,login,log=print,limit=TAKE,cfg=None):
    """Последние превью с каналов-образцов: заданные вручную (pipeline.preview.channels) + лучшие найденные нарезчики.
    Без ручных каналов — как раньше, только лучший нарезчик. Старые образцы сверх KEEP удаляются."""
    from reaction_previews import download_thumbnail
    import channel_stats as cs
    pins=pinned_channels(login,cfg);client=cs._Client();sources=[]
    for ref in pins:
        try:
            cid=resolve_channel_id(client,ref)
            if cid in {s['id'] for s in sources}:continue
            p=_channel_profile(client,cid)
        except Exception as exc:
            log(f'Канал {ref}: не прочитан ({type(exc).__name__}: {str(exc)[:120]})');continue
        if not p['videos']:
            log(f'Канал {ref}: нет длинных видео — пропускаю');continue
        sources.append(_source_row(p,{'title':p['title'] or ref,'pinned':True}))
        log(f"Свой канал-образец: «{sources[-1]['title']}» — видео на странице {len(p['videos'])}")
    ranked=[]
    try:ranked=rank_clip_channels(root,login,log)
    except Exception as exc:
        if not sources:raise
        log(f'Автопоиск нарезчиков не удался: {type(exc).__name__}: {str(exc)[:150]}')
    fresh=[r for r in ranked if r['last_days'] is not None and r['last_days']<=STALE_DAYS] or ranked
    top=fresh[0]['score'] if fresh and fresh[0]['score'] else 0
    picked=fresh[:AUTO_WITH_PINNED] if sources else [r for r in fresh[:AUTO_NO_PINNED] if r is fresh[0] or (r['score'] or 0)>=top*0.7]
    for r in picked:
        if r['id'] in {s['id'] for s in sources}:continue
        sources.append(r)
        log(f"Нарезчик: «{r['title']}» — подписчиков {r['subs']}, медиана просмотров {r['median_views']}, "
            f"последнее видео {('%.0f дн. назад' % r['last_days']) if r['last_days'] is not None else 'неизвестно'}")
    if not sources:
        raise RuntimeError(f'Не найдено каналов с нарезками {login} на YouTube: укажите каналы-образцы в разделе «Превью»')
    best=sources[0]
    folder=auto_dir(root,login);folder.mkdir(parents=True,exist_ok=True)
    per=max(3,min(limit,KEEP//len(sources)))
    saved=0;per_source={}
    for s in sources:
        got=0
        for v in s['videos'][:per]:
            target=folder/f"{s['id']}_{v['id']}.jpg"
            if target.exists():got+=1;continue
            try:
                image,_=download_thumbnail(v['id']);image.save(target,'JPEG',quality=92);saved+=1;got+=1
            except Exception:
                continue
        per_source[s['id']]=got
    ids={s['id'] for s in sources}
    # В пуле — только превью выбранных каналов: картинки прежних каналов убираются.
    for img in list_images(folder):
        if os.path.basename(str(img))[:24] not in ids:
            try:os.remove(img)
            except OSError:pass
    for cid in ids:    # у каждого канала — не больше per свежих образцов
        files=sorted((f for f in list_images(folder) if f.name.startswith(cid+'_')),key=lambda f:os.path.getmtime(f),reverse=True)
        for old in files[per:]:
            try:os.remove(old)
            except OSError:pass
    total=len(list_images(folder))
    info={'updated':time.time(),'channel':{k:best[k] for k in ('id','title','subs','median_views','last_days','score')},
          'pinned':pins,
          'candidates':[{k:r[k] for k in ('id','title','subs','median_views','last_days','about','score')} for r in ranked[:6]],
          'channels':[{'id':s['id'],'name':s['title'],'pinned':bool(s.get('pinned')),'templates':per_source.get(s['id'],0)} for s in sources]}
    (folder/'channels.json').write_text(json.dumps(info,ensure_ascii=False,indent=1),encoding='utf-8')
    log(f"Каналы-образцы: {', '.join(s['title'] for s in sources)}; новых образцов {saved}, всего в папке {total}")
    return saved,[s['title'] for s in sources]


def auto_needs_refresh(root,login,cfg=None):
    try:
        info=json.loads((auto_dir(root,login)/'channels.json').read_text(encoding='utf-8'))
        if 'channel' not in info:return True        # выбран старым способом — пересобрать
        if list(info.get('pinned') or [])!=pinned_channels(login,cfg):return True    # список своих каналов изменился
        return time.time()-float(info.get('updated') or 0)>REFRESH_DAYS*86400
    except (OSError,ValueError):
        return True


def pick_templates(root,login,cfg,log=print,count=3):
    mode=template_mode(cfg,login)
    manual=list_images(manual_dir(root,login));auto=list_images(auto_dir(root,login))
    if mode=='manual':
        pool=manual or auto
    else:
        if not auto or auto_needs_refresh(root,login,cfg):
            log('Обновляю образцы превью с лучшего канала нарезок' if auto else 'Шаблонов с чужих каналов ещё нет — ищу каналы нарезок на YouTube')
            try:refresh_auto(root,login,log,cfg=cfg);auto=list_images(auto_dir(root,login))
            except Exception as exc:log(f'Автопоиск шаблонов не удался: {exc}')
        pool=auto or manual
    if not pool:
        raise RuntimeError(f'Нет шаблонов превью для {login}: добавьте картинки в thumbnail_templates/{login} или найдите каналы нарезок в разделе «Превью»')
    return random.sample(pool,min(count,len(pool)))


def caption_and_context(row):
    text=re.sub(r'\s+',' ',str(row.get('preview_text') or '')).strip()
    if not text:
        words=re.sub(r'[«»"]','',str(row.get('title') or '')).split()
        text=' '.join(words[:4])
    context=re.sub(r'\s+',' ',str(row.get('preview_context') or '')).strip() or str(row.get('title') or '').strip()
    return text,context


def generate(root,finder,login,row,target,cfg,log=print):
    """Ask ChatGPT for a preview; save it as <clip> — ИИ-превью.jpg (1280×720) with a JSON report."""
    from PIL import Image,ImageOps
    if not login:raise RuntimeError('Не указан стример для превью')
    target=Path(target)
    if target.exists():raise RuntimeError('Превью уже существует; не перезаписываю')
    text,context=caption_and_context(row)
    if not text:raise RuntimeError('Нет надписи для превью')
    templates=pick_templates(root,login,cfg,log)
    prompt=build_prompt(cfg,login,text,context)
    path,used=finder.generate_image(prompt,templates,log=log)
    with Image.open(path) as im:
        out=ImageOps.fit(im.convert('RGB'),(1280,720),Image.Resampling.LANCZOS)
    target.parent.mkdir(parents=True,exist_ok=True)
    fd,tmp=tempfile.mkstemp(prefix='.preview-',suffix='.jpg',dir=target.parent);os.close(fd)
    try:
        out.save(tmp,'JPEG',quality=93,optimize=True)
        if target.exists():raise RuntimeError('Превью уже существует; не перезаписываю')
        os.replace(tmp,target)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
    info={'status':'готово','generator':'ChatGPT (генерация по шаблону)','preview_text':text,'context':context,
          'template':os.path.basename(str(used)),'templates_tried':[os.path.basename(str(t)) for t in templates],
          'template_mode':template_mode(cfg,login),'prompt':prompt}
    target.with_suffix('.json').write_text(json.dumps(info,ensure_ascii=False,indent=2),encoding='utf-8')
    return info


def generate_for_clip(root,finder,video,login,cfg,log=print,new_copy=True):
    """On-demand preview for a finished clip (reads its .pipeline.json; no transcription, no new moments request)."""
    video=Path(video);directory=video.parent
    job=directory.parent if directory.name in ('Готовые нарезки','Готовые без тишины') else directory
    try:row=json.loads((job/(video.stem+'.pipeline.json')).read_text(encoding='utf-8-sig'))['reaction']
    except (OSError,ValueError,KeyError):raise RuntimeError('Не найдены данные нарезки (.pipeline.json) — выберите файл из папки recordings')
    target=video.with_name(video.stem+' — ИИ-превью.jpg')
    if target.exists() and new_copy:
        for n in range(2,1000):
            cand=video.with_name(f'{video.stem} — ИИ-превью ({n}).jpg')
            if not cand.exists():target=cand;break
    info=generate(root,finder,login,row,target,cfg,log)
    info['path']=str(target)
    return info
